begin;
select no_plan();
select ok((select not enabled and not license_approved and retention_seconds=604800 from private.map_baseline_config),'Baseline opt-in and licensing default off, max seven-day policy');
select ok((select bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('map_baseline_config','map_baseline_tiles')),'New private tables have RLS');
select ok(not has_table_privilege('anon','private.map_baseline_tiles','SELECT'),'No guest table access');
select ok(not has_table_privilege('authenticated','private.map_baseline_tiles','SELECT'),'No member table access');
select ok(not has_table_privilege('service_role','private.map_baseline_tiles','SELECT'),'Service uses bounded RPC only');
select ok(not has_function_privilege('authenticated','public.reserve_basemap_tile_v2(uuid,integer,integer,integer,boolean)','EXECUTE'),'No member impersonation RPC');
select ok(not has_function_privilege('anon','public.finish_basemap_tile_v2(integer,integer,integer,uuid,text)','EXECUTE'),'No guest writes');
select ok(has_function_privilege('service_role','public.reserve_basemap_tile_v2(uuid,integer,integer,integer,boolean)','EXECUTE'),'Service reserve grant');
select ok(has_function_privilege('service_role','public.finish_basemap_tile_v2(integer,integer,integer,uuid,text)','EXECUTE'),'Service finish grant');
select ok(not has_function_privilege('service_role','private.basemap_ancestor_v2(integer,integer,integer)','EXECUTE'),'No cache-only gate bypass');
set local timezone='Europe/Rome';
select is(private.basemap_retry_v2('2026-10-25T00:00:00Z'),86400,'UTC reset ignores the autumn daylight-saving day');
select is(private.basemap_retry_v2('2026-03-29T00:00:00Z'),86400,'UTC reset ignores the spring daylight-saving day');
set local timezone='UTC';
select is(length(private.basemap_tile_payload_v2(12,2174,1456,decode(repeat('00',262144),'hex'),statement_timestamp()+interval '1 day',statement_timestamp())->>'image_base64'),349528,'Full compressed-byte bound fits the v2 base64 envelope');
select is(position(E'\n' in (private.basemap_tile_payload_v2(12,2174,1456,decode(repeat('00',262144),'hex'),statement_timestamp()+interval '1 day',statement_timestamp())->>'image_base64')),0,'Server base64 line folding cannot reject a valid bounded transport');
select ok((select bool_and(prosecdef and proconfig @> array['search_path=""']) from pg_proc where proname in ('reserve_basemap_tile_v2','finish_basemap_tile_v2')),'Hardened security-definer boundaries');
insert into auth.users(id,email) values('a9530000-0000-4000-8000-000000000001','map-cost-a@planets.invalid'),('a9530000-0000-4000-8000-000000000002','map-cost-b@planets.invalid');
insert into public.profiles(id,display_name) values('a9530000-0000-4000-8000-000000000001','MAP-COST A'),('a9530000-0000-4000-8000-000000000002','MAP-COST B');
delete from private.location_provider_usage;
select is(public.reserve_basemap_tile_v2(null,12,2174,1456,true)->>'status','guest_disabled','Guests denied even for cache-only');
select throws_ok($$select public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',19,1,1,false)$$,'22023','Invalid basemap tile.','Zoom bounds');
select throws_ok($$select public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',12,4096,1,false)$$,'22023','Invalid basemap tile.','XYZ bounds');
update private.location_provider_config set enabled=true,tiles_enabled=true,cache_license_approved=true,tile_cache_seconds=60,daily_units_limit=8000,actor_daily_units=8000,failure_streak=0,blocked_until=null;
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',12,2174,1456,false)->>'status','disabled','Separate baseline gate');
update private.map_baseline_config set enabled=true;
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',12,2174,1456,false)->>'status','unconfigured','Separate long-retention license gate');
update private.map_baseline_config set license_approved=true;
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',12,2174,1456,true)->>'status','cache_miss','Cache-only cold miss is honest');
select is((select count(*) from private.map_baseline_tiles),0::bigint,'Cache-only creates no claim');
select is((select coalesce(sum(used),0) from private.location_provider_usage where scope='units:global'),0::bigint,'Cache-only reserves zero credits');
select set_config('test.cost.claim',public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',12,2174,1456,false)::text,true);
select is(current_setting('test.cost.claim')::jsonb->>'cached','false','Baseline cold miss has one charged claim');
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000002',12,2174,1456,false)->>'status','pending','Concurrent baseline miss coalesces');
select is((select used from private.location_provider_usage where scope='units:global'),1,'Only final winner charged one quarter unit');
select throws_ok($$select public.finish_basemap_tile_v2(12,2174,1456,(current_setting('test.cost.claim')::jsonb->>'token')::uuid,'aW52YWxpZA==')$$,'22023','Invalid map tile.','Malformed PNG rejected');
select is(public.finish_basemap_tile_v2(12,2174,1456,(current_setting('test.cost.claim')::jsonb->>'token')::uuid,
 encode(decode('89504e470d0a1a0a0000000d4948445200000100000001000806000000000000000000000049454e44ae426082','hex'),'base64'))->>'status','ok','Synthetic SQL header fixture finishes baseline');
select set_config('test.cost.expiry',(select expires_at::text from private.map_baseline_tiles where x=2174 and y=1456),true);
update private.location_provider_config set daily_units_limit=1,actor_daily_units=1;
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',12,2174,1456,false)->>'cached','true','Exact baseline hit before global/actor ceiling');
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',14,8698,5824,false)->'source'->>'z','12','Budget exhaustion returns true covering source zoom');
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',14,8698,5824,false)->>'budget_exhausted','true','Daily budget is distinguished from other failures');
select ok((public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',14,8698,5824,false)->>'retry_after_seconds')::integer between 1 and 86400,'Reset comes from server UTC day');
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000002',14,8698,5824,true)->'source'->>'x','2174','Fresh actor can read already stored covering base at cap');
select is((select used from private.location_provider_usage where scope='units:global'),1,'All cache/fallback calls have zero new units');
select is((select expires_at::text from private.map_baseline_tiles where x=2174 and y=1456),current_setting('test.cost.expiry'),'Reads never slide source expiry');
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',14,1000,1000,true)->>'status','cache_miss','Outside Trento is never substituted');
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',11,1087,728,true)->>'status','cache_miss','Zooming out cannot use a geographically incomplete parent');
update private.location_provider_config set actor_minute_requests=1;
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',14,8698,5824,true)->>'status','rate_limited','Cache-only respects ordinary rate limits');
update private.location_provider_config set actor_minute_requests=120,blocked_until=statement_timestamp()+interval '30 seconds';
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',14,8698,5824,true)->>'status','unavailable','Circuit breaker is not budget exhaustion');
update private.location_provider_config set blocked_until=null,enabled=false;
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',14,8698,5824,true)->>'status','disabled','Master revocation blocks cached base');
update private.location_provider_config set enabled=true;
update private.map_baseline_config set revision=revision+1;
select is(public.reserve_basemap_tile_v2('a9530000-0000-4000-8000-000000000001',14,8698,5824,true)->>'status','cache_miss','Operator revision invalidates and prunes old base');
select is((select count(*) from private.map_baseline_tiles),0::bigint,'Bounded physical pruning');
select throws_ok($$update private.map_baseline_config set retention_seconds=604801$$,'23514',null,'Maximum seven days is enforced');
select throws_ok($$insert into private.map_baseline_tiles(z,x,y,revision,state,expires_at) values(12,2176,1456,1,'pending',statement_timestamp()+interval '30 seconds')$$,'23514',null,'Baseline extent cannot follow arbitrary searches');
select * from finish();
rollback;
